using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    int p;
    cin >> s >> p;
    unordered_map<string, int> ids; // distinct product -> id
    vector<int> target;
    int width = 0;
    for (int i = 0; i < p; i++) {
        string word;
        cin >> word;
        width = word.size();
        auto [it, added] = ids.emplace(word, (int)target.size());
        if (added) target.push_back(0);
        target[it->second]++;
    }
    int len = s.size();
    // word[i]: id of the product starting at position i, or -1.
    vector<int> word(max(0, len - width + 1), -1);
    for (int i = 0; i + width <= len; i++) {
        auto it = ids.find(s.substr(i, width));
        if (it != ids.end()) word[i] = it->second;
    }
    long long answer = 0;
    vector<int> freq(target.size());
    // One sliding window of whole words per start offset.
    for (int offset = 0; offset < width; offset++) {
        fill(freq.begin(), freq.end(), 0);
        int left = offset, count = 0;
        for (int right = offset; right + width <= len; right += width) {
            int w = word[right];
            if (w < 0) {
                // Not a product: empty the window and restart after this word.
                for (; left < right; left += width) freq[word[left]]--;
                left = right + width;
                count = 0;
                continue;
            }
            freq[w]++;
            count++;
            while (freq[w] > target[w]) {
                freq[word[left]]--;
                count--;
                left += width;
            }
