import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static String next() throws IOException {
        int c = skipSpaces();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    private static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int p = nextInt();
        HashMap<String, Integer> ids = new HashMap<>(); // distinct product -> id
        int[] target = new int[p];
        int width = 0;
        for (int i = 0; i < p; i++) {
            String product = next();
            width = product.length();
            Integer id = ids.get(product);
            if (id == null) {
                id = ids.size();
                ids.put(product, id);
            }
            target[id]++;
        }
        int len = s.length();
        // word[i]: id of the product starting at position i, or -1.
        int[] word = new int[Math.max(0, len - width + 1)];
        for (int i = 0; i + width <= len; i++) word[i] = ids.getOrDefault(s.substring(i, i + width), -1);
        long answer = 0;
        int[] freq = new int[ids.size()];
        // One sliding window of whole words per start offset.
        for (int offset = 0; offset < width; offset++) {
            Arrays.fill(freq, 0);
            int left = offset, count = 0;
            for (int right = offset; right + width <= len; right += width) {
                int w = word[right];
                if (w < 0) {
                    // Not a product: empty the window and restart after this word.
                    for (; left < right; left += width) freq[word[left]]--;
                    left = right + width;
                    count = 0;
                    continue;
                }
                freq[w]++;
                count++;
                while (freq[w] > target[w]) {
                    freq[word[left]]--;
                    count--;
                    left += width;
                }
                if (count == p) answer++;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := next()
	p := nextInt()
	ids := map[string]int{} // distinct product -> id
	var target []int
	width := 0
	for i := 0; i < p; i++ {
		product := next()
		width = len(product)
		id, ok := ids[string(product)]
		if !ok {
			id = len(target)
			ids[string(product)] = id
			target = append(target, 0)
		}
		target[id]++
	}
	n := len(s)
	// word[i]: id of the product starting at position i, or -1.
	word := make([]int, max(0, n-width+1))
	for i := range word {
		if id, ok := ids[string(s[i:i+width])]; ok {
			word[i] = id
		} else {
			word[i] = -1
		}
	}
	answer := 0
	freq := make([]int, len(target))
	// One sliding window of whole words per start offset.
	for offset := 0; offset < width; offset++ {
		clear(freq)
		left, count := offset, 0
		for right := offset; right+width <= n; right += width {
			w := word[right]
			if w < 0 {
				// Not a product: empty the window and restart after this word.
				for ; left < right; left += width {
					freq[word[left]]--
				}
				left = right + width
				count = 0
				continue
			}
			freq[w]++
			count++
			for freq[w] > target[w] {
				freq[word[left]]--
				count--
				left += width
			}
			if count == p {
				answer++
			}
		}
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
